// packages/core/src/standing.ts
var STANDING_LIMITS = {
  minimumDeveloperAccountAgeDays: 14,
  minimumReturningPlayerCount: 20,
  /** Different days a player's plays counted on the developer's games, for the player to be a returning one. */
  minimumReturningPlayerCountedDayCount: 2,
  /** A returning player's own account: this old, with plays counted on this many different days on any game. */
  minimumPlayerAccountAgeDays: 7,
  minimumPlayerCountedDayCount: 3,
  /** After a version is rejected or a game taken down, the developer's powers wait this long. */
  rulingWaitDurationDays: 30,
  /** What a new 16–17 account types reaches only friends until it's this old, with plays counted on this many different days. */
  minimumStrangerChatAccountAgeHours: 24,
  minimumStrangerChatCountedDayCount: 2
};
var DAY_MS = 864e5;
var NO_STANDING = {
  isEstablishedDeveloper: false,
  outsideLinksEnabled: false,
  searchEnginesEnabled: false,
  returningPlayerCount: 0,
  accountAgeDays: 0,
  lastRulingAtMs: null,
  rulingWaitEndsAtMs: null,
  hasCardOrStripeAccount: false,
  hasPaidByCard: false,
  isBanned: false
};
function rulingWaitEndsAt(lastRulingAtMs, nowMs) {
  if (lastRulingAtMs === null) return null;
  const endsAtMs = lastRulingAtMs + STANDING_LIMITS.rulingWaitDurationDays * DAY_MS;
  return endsAtMs > nowMs ? endsAtMs : null;
}
async function standingOf(database, ownerId, nowMs) {
  if (!ownerId) return NO_STANDING;
  const row3 = await database.prepare(
    `SELECT owners.is_established, owners.is_zaisma_account, owners.is_invited_developer, owners.returning_player_count, owners.last_ruling_at_ms, owners.created_at_ms AS owner_created_at_ms,
        owners.stripe_account_id, owners.can_take_stripe_payments, accounts.created_at_ms AS account_created_at_ms, accounts.banned_at_ms,
        EXISTS (SELECT 1 FROM owner_cards WHERE owner_cards.owner_id = owners.id AND NOT EXISTS (SELECT 1 FROM banned_marks WHERE banned_marks.mark_kind = 'card' AND banned_marks.mark_sha256 = owner_cards.card_fingerprint_sha256)) AS has_card
      FROM owners LEFT JOIN accounts ON accounts.id = owners.account_id WHERE owners.id = ?`
  ).bind(ownerId).first();
  if (!row3) return NO_STANDING;
  const accountAgeDays = Math.max(0, Math.floor((nowMs - (row3.account_created_at_ms ?? row3.owner_created_at_ms)) / DAY_MS));
  const rulingWaitEndsAtMs = rulingWaitEndsAt(row3.last_ruling_at_ms, nowMs);
  const hasCardOrStripeAccount = row3.has_card === 1 || row3.stripe_account_id !== null && row3.can_take_stripe_payments === 1;
  const isBanned = row3.banned_at_ms !== null;
  const facts = { returningPlayerCount: row3.returning_player_count, accountAgeDays, lastRulingAtMs: row3.last_ruling_at_ms, rulingWaitEndsAtMs, hasCardOrStripeAccount, hasPaidByCard: row3.has_card === 1, isBanned };
  if (isBanned || rulingWaitEndsAtMs !== null) return { ...NO_STANDING, ...facts };
  const isEstablishedDeveloper = row3.is_established === 1 || row3.is_zaisma_account === 1 || row3.is_invited_developer === 1;
  const outsideLinksEnabled = isEstablishedDeveloper || hasCardOrStripeAccount;
  return { ...facts, isEstablishedDeveloper, outsideLinksEnabled, searchEnginesEnabled: isEstablishedDeveloper };
}
async function noteRuling(database, ownerId, nowMs, subject = { gameId: null, versionId: null }) {
  await database.batch([
    database.prepare("INSERT INTO standing_rulings (owner_id, game_id, version_id, ruled_at_ms) VALUES (?, ?, ?, ?)").bind(ownerId, subject.gameId, subject.versionId, nowMs),
    database.prepare("UPDATE owners SET last_ruling_at_ms = ?, is_established = 0 WHERE id = ?").bind(nowMs, ownerId)
  ]);
}
async function overturnVersionRuling(database, versionId2, nowMs) {
  const overturned = await database.prepare("UPDATE standing_rulings SET overturned_at_ms = ? WHERE version_id = ? AND overturned_at_ms IS NULL RETURNING owner_id").bind(nowMs, versionId2).all();
  const ownerIds = [...new Set(overturned.results.map((row3) => row3.owner_id))];
  if (ownerIds.length === 0) return false;
  await database.batch(
    ownerIds.map(
      (ownerId) => database.prepare(
        `UPDATE owners SET last_ruling_at_ms = (SELECT CASE WHEN MAX(ruled_at_ms) IS NULL OR owners.last_ruling_at_ms IS NULL THEN NULL ELSE MIN(MAX(ruled_at_ms), owners.last_ruling_at_ms) END
            FROM standing_rulings WHERE owner_id = ?1 AND overturned_at_ms IS NULL), standing_checked_at_ms = NULL WHERE id = ?1`
      ).bind(ownerId)
    )
  );
  return true;
}

