// apps/site/src/components/first-paint-script.ts
var THEME_SCRIPT = `/* theme */(function () {
  var root = document.documentElement, query = window.matchMedia("(prefers-color-scheme: dark)"), listeners = [];
  function choice() { var saved = root.getAttribute("data-theme-choice"); return saved === "light" || saved === "dark" ? saved : "system"; }
  function now() { return choice() === "system" ? (query.matches ? "dark" : "light") : choice(); }
  function apply() { var theme = now(); if (root.getAttribute("data-theme") === theme) return; root.setAttribute("data-theme", theme); listeners.forEach(function (listener) { listener(theme); }); }
  if (query.addEventListener) query.addEventListener("change", apply);
  // A choice changed on the page itself (Screens sets each frame's) shows at once.
  new MutationObserver(apply).observe(root, { attributes: true, attributeFilter: ["data-theme-choice"] });
  window.zaismaTheme = { now: now, choice: choice, onChange: function (listener) { listeners.push(listener); } };
  apply();
})();
`;
var CUTOUT_SIDE_SCRIPT = `/* cutout side */(function () {
  if (!/iPhone/.test(navigator.userAgent)) return;
  var root = document.documentElement;
  function apply() { var turned = window.orientation; if (turned === 90) root.setAttribute("data-cutout-side", "left"); else if (turned === -90) root.setAttribute("data-cutout-side", "right"); else root.removeAttribute("data-cutout-side"); }
  window.addEventListener("orientationchange", apply);
  apply();
})();
`;
var FOLLOWING_PARTS_RETRY_MS = 1e3;
var FOLLOWING_FILES_SCRIPT = `/* following files */(function () {
  var isRead = document.readyState !== "loading", isRun = false, isPartsIn = true;
  function runFiles() {
    if (isRun || !isRead || !isPartsIn) return;
    isRun = true;
    // A page prepared ahead of a tap (prepared-pages.ts) holds the files it marks until it's opened: nothing counts or wakes before then.
    var held = [], last = null;
    function run(named) { var script = document.createElement("script"); script.src = named.href; script.async = false; document.body.appendChild(script); return script; }
    document.querySelectorAll("link[rel=preload][data-page-script]").forEach(function (named) { if (document.prerendering && named.hasAttribute("data-when-opened")) held.push(named); else last = run(named); });
    if (held.length) document.addEventListener("prerenderingchange", function () { held.forEach(run); }, { once: true });
    // In order, so the last one's load comes once every file has run: the page's own work is done (afterSettling).
    function settled() { if (window.zaismaWatch) window.zaismaWatch.settled(); }
    if (last) { last.addEventListener("load", settled); last.addEventListener("error", settled); } else settled();
  }
  function putParts() {
    var holder = document.querySelector("div[hidden][data-following-parts]"), partsUrl = null;
    try { partsUrl = holder && new URL(holder.getAttribute("data-following-parts"), location.href); } catch (error) {}
    // Only the page's own HTML, from its own address: a holder naming anywhere else is left alone.
    if (!holder || !partsUrl || partsUrl.origin !== location.origin) return;
    isPartsIn = false;
    function partsIn() { isPartsIn = true; runFiles(); }
    function ask(retryCount) {
      fetch(partsUrl.href, { credentials: "same-origin" })
        .then(function (answer) { if (!answer.ok) throw new Error("parts " + answer.status); return answer.text(); })
        .then(function (text) { var parts = document.createElement("template"); parts.innerHTML = text; holder.replaceWith(parts.content); partsIn(); })
        .catch(function () { if (retryCount > 0) setTimeout(function () { ask(retryCount - 1); }, ${FOLLOWING_PARTS_RETRY_MS}); else partsIn(); });
    }
    // A page prepared ahead fetches nothing until it's opened (prepared-pages.ts); its script files wait for these parts.
    if (document.prerendering) document.addEventListener("prerenderingchange", function () { ask(1); }, { once: true });
    else ask(1);
  }
  if (isRead) { putParts(); runFiles(); }
  else document.addEventListener("readystatechange", function read() { if (document.readyState === "loading") return; document.removeEventListener("readystatechange", read); isRead = true; putParts(); runFiles(); });
})();
`;
var MEASURED_GLASS_SCRIPT = `/* measured glass */(function () {
  if (!window.zaismaWatch) return;
  function hostOf(el) { return el.closest(":has(> .backdrop)"); }
  function pickOf(host) {
    var measured = host && host.querySelector(":scope > .backdrop[data-adapts-glass][data-glass-kind], :scope > .backdrop .backdrop[data-adapts-glass][data-glass-kind]");
    return measured ? { isSmoked: measured.getAttribute("data-glass-kind") === "smoked", tint: measured.getAttribute("data-glass-tint") || "" } : null;
  }
  function setGlass(el, pick) {
    el.classList.toggle("smoke", pick.isSmoked);
    if (pick.isSmoked) el.removeAttribute("data-theme-choice"); else if (!el.hasAttribute("data-theme-choice")) el.setAttribute("data-theme-choice", "light");
    if (pick.tint) el.style.setProperty("--glass-tint", pick.tint);
  }
  // What holds the world takes its glass too (BACKDROP_SCRIPT's showPick does the same once it measures): what's laid straight on the
  // page outside a pane, the page's rail, is smoked or light with the glass round it from the first paint.
  function setHost(host, pick) {
    if (host.ownThemeChoice === undefined) host.ownThemeChoice = host.getAttribute("data-theme-choice");
    host.classList.toggle("smoke", pick.isSmoked);
    if (pick.isSmoked) host.removeAttribute("data-theme-choice"); else host.setAttribute("data-theme-choice", host.ownThemeChoice || "light");
  }
  window.zaismaWatch.eachArriving("[data-adapts-glass][data-glass-kind]", function (backdrop) {
    var host = backdrop.parentElement, hostPick = pickOf(host);
    if (host && hostPick) setHost(host, hostPick);
    document.querySelectorAll("[data-glass]:not([data-cut-line])").forEach(function (el) { var host = hostOf(el), pick = pickOf(host); if (pick) setGlass(el, pick); });
  });
  window.zaismaWatch.eachArriving("[data-glass]:not([data-cut-line])", function (el) { var host = hostOf(el), pick = pickOf(host); if (pick) setGlass(el, pick); });
})();
`;
var FRAME_SAYS_LIMIT_MS = 4e3;
var SHOWN_ONCE_DRAWN_SCRIPT = `/* shown once drawn */(function () {
  var FRAMES = "iframe[data-shows-once-drawn]";
  // Once the page's panes have faded in and its own work is done, as a picture does (PICTURE_SCRIPT): the glass over it would blur a
  // changing world every frame, and the fade would drop frames under the page's styles being worked out again.
  function show(frame) { window.zaismaWatch.afterSettling(function () { frame.classList.add("is-shown"); }); }
  window.addEventListener("message", function (event) {
    if (!event.data || !event.data.zaismaBackground) return;
    document.querySelectorAll(FRAMES).forEach(function (frame) { if (event.source === frame.contentWindow) { frame.hasSaid = true; show(frame); } });
  });
  window.zaismaWatch.eachArriving(FRAMES, function (frame) {
    frame.addEventListener("load", function () { setTimeout(function () { if (!frame.hasSaid) show(frame); }, ${FRAME_SAYS_LIMIT_MS}); });
  });
})();
`;
var HIDDEN_AMOUNTS_SCRIPT = String.raw`/* hidden amounts */(function () {
  var KEY = "zaisma.payments_amounts_hidden";
  var hidden = false;
  try { hidden = localStorage.getItem(KEY) === "yes"; } catch (e) {}
  var AMOUNTS = "#payments .number-amount, [data-amount]", TOGGLES = "[data-amounts-toggle]";
  function drawAmount(each) {
    if (!each.hasAttribute("data-amount")) each.setAttribute("data-amount", each.textContent);
    each.textContent = hidden ? "•••" : each.getAttribute("data-amount");
  }
  function drawToggle(button) {
    button.setAttribute("aria-pressed", String(hidden));
    var label = button.querySelector("span:not([class])");
    if (label) label.textContent = hidden ? "Show amounts" : "Hide amounts";
  }
  function draw() { document.querySelectorAll(AMOUNTS).forEach(drawAmount); document.querySelectorAll(TOGGLES).forEach(drawToggle); }
  window.zaismaWatch.each(AMOUNTS, drawAmount);
  window.zaismaWatch.each(TOGGLES, drawToggle);
  document.addEventListener("click", function (event) {
    var button = event.target.closest && event.target.closest("[data-amounts-toggle]");
    if (!button) return;
    hidden = !hidden;
    try { localStorage.setItem(KEY, hidden ? "yes" : "no"); } catch (e) {}
    draw();
  });
})();
`;
var ACCOUNT_LINK_SCRIPT = `/* account link */(function () {
  if (!/(^|; )(__Host-)?zaisma_in=1/.test(document.cookie)) return;
  window.zaismaWatch.each("header.top[data-account-from-cookie] .end > a:is(.run-wrap,.cut-btn)", function (link) {
    link.href = "/account"; var words = link.querySelector(".face > span:not([class])"); if (words) words.textContent = "Account";
  });
})();
`;

