    td = smin(td, limb(q, vec2(0.0, 0.19), vec2(-0.04, 0.3), vec2(-0.09, 0.42), 0.02), 0.03);
    td = smin(td, limb(q, vec2(0.01, 0.19), vec2(0.08, 0.3), vec2(0.07, 0.43), 0.02), 0.03);
