    titleId: `${id}-title`,
    body: html``,
    parts: paneParts({ head: { words: html``, end: close }, body: html`<div class="sheet-scroll"><div class="sheet-body scrolls to-edge confirm-body">${body}</div></div>` }),
    closeButton: close,
