function comparison(options) {
  const ourIndex = options.columns.findIndex((column) => column.isOurs);
  const answer = (isYes) => isYes ? html`<span class="comparison-yes">${icon("check")}<span class="sr">Yes</span></span>` : html`<span class="comparison-no"><span class="sr">No</span></span>`;
  return html`<div class="comparison" data-fades-sideways style="--comparison-columns:${String(options.columns.length)};--comparison-ours:${String(ourIndex + 2)}"><div class="comparison-in">${ourIndex >= 0 ? html`<span class="comparison-ours-slab" aria-hidden="true">${slab({ body: html``, kind: "comparison-slab" })}</span>` : ""}<table aria-label="${options.label}"><thead><tr><td></td>${options.columns.map((column) => html`<th scope="col"${column.isOurs ? html` class="is-ours"` : ""}><span class="comparison-head">${icon(column.icon)}<span>${column.label}</span></span></th>`)}</tr></thead><tbody>${options.rows.map(
    (row3) => html`<tr><th scope="row">${row3.question}</th>${row3.answers.map((isYes, index) => html`<td${options.columns[index]?.isOurs ? html` class="is-ours"` : ""}>${answer(isYes)}</td>`)}</tr>`
  )}</tbody></table></div></div>`;
}
var COMPARISON_STYLES = `
/* A comparison: a grid of questions and answers, hairlines between rows, the column it's about raised on a slab behind its cells. */
.comparison { container-type: inline-size; overflow-x: auto; min-width: 0; }
.comparison-in { position: relative; min-width: calc(7.5rem + var(--comparison-columns) * 4rem); padding-block: var(--gap-words-words); }
.comparison-in > table { position: relative; width: 100%; border-collapse: collapse; table-layout: fixed; font: var(--type-words); color: var(--ink); }
.comparison :is(th, td) { padding: var(--pad-inside-words); text-align: center; vertical-align: middle; border-bottom: 1px solid var(--line); position: relative; z-index: 1; }
.comparison tbody tr:last-child > * { border-bottom: none; }
.comparison thead th { font: var(--type-facts); color: var(--ink-2); }
.comparison thead th.is-ours { color: var(--ink); }
.comparison tbody th { text-align: start; font: var(--type-label); color: var(--ink); padding-inline-start: var(--pad-words); }
/* The questions' column takes 40% (its width set on the header row, which a fixed table sizes its columns by); the rest share what's left. */
.comparison thead td:first-child { width: 40%; }
.comparison-head { display: inline-flex; flex-direction: column; align-items: center; gap: var(--gap-words-words); }
.comparison-head > .ico { width: 28px; height: 28px; color: var(--ink); }
.comparison-yes { display: inline-flex; color: var(--ink); }
.comparison-yes > .ico { width: 22px; height: 22px; stroke-width: 2.2; }
.comparison-no { display: inline-block; width: 14px; height: 2px; background: var(--line); vertical-align: middle; }
/* The slab behind the column it's about: as tall as the table and as wide as one column, at that column's place. */
.comparison-ours-slab { position: absolute; inset-block: 0; inset-inline-start: calc(40% + (var(--comparison-ours) - 2) * 60% / var(--comparison-columns)); width: calc(60% / var(--comparison-columns)); z-index: 0; }
.comparison-ours-slab > .comparison-slab, .comparison-ours-slab > .comparison-slab > .slab { display: block; width: 100%; height: 100%; }
@container (max-width: 40rem) { .comparison thead td:first-child { width: 7.5rem; } .comparison-ours-slab { inset-inline-start: calc(7.5rem + (var(--comparison-ours) - 2) * (100% - 7.5rem) / var(--comparison-columns)); width: calc((100% - 7.5rem) / var(--comparison-columns)); } }
`;
