function hoverOnlyWherePointing(css) {
  let out = "", readIndex = 0;
  const blockEnd = (openIndex) => {
    let nestingLevel = 0;
    for (let i2 = openIndex; i2 < css.length; i2++) {
      const character = css[i2];
      if (character === "/" && css[i2 + 1] === "*") {
        i2 = css.indexOf("*/", i2 + 2) + 1;
        continue;
      }
      if (character === '"' || character === "'") {
        i2 = css.indexOf(character, i2 + 1);
        continue;
      }
      if (character === "{") nestingLevel++;
      else if (character === "}" && --nestingLevel === 0) return i2;
    }
    return css.length - 1;
  };
  while (readIndex < css.length) {
    if (css.startsWith("/*", readIndex)) {
      const endIndex = css.indexOf("*/", readIndex + 2) + 2;
      out += css.slice(readIndex, endIndex);
      readIndex = endIndex;
      continue;
    }
    const openIndex = css.indexOf("{", readIndex);
    if (openIndex < 0) {
      out += css.slice(readIndex);
      break;
    }
    const commentIndex = css.slice(readIndex, openIndex).lastIndexOf("*/");
    if (commentIndex >= 0) {
      out += css.slice(readIndex, readIndex + commentIndex + 2);
      readIndex += commentIndex + 2;
      continue;
    }
    const head = css.slice(readIndex, openIndex), closeIndex = blockEnd(openIndex), body = css.slice(openIndex + 1, closeIndex);
    const selector = head.trim();
    if (/^@(media|supports|container|layer)\b/.test(selector)) out += `${head}{${hoverOnlyWherePointing(body)}}`;
    else if (selector.startsWith("@") || !selector.includes(":hover")) out += `${head}{${body}}`;
    else {
      const parts2 = [];
      let nestingLevel = 0, partStartIndex = 0;
      for (let i2 = 0; i2 < selector.length; i2++) {
        if (selector[i2] === "(") nestingLevel++;
        else if (selector[i2] === ")") nestingLevel--;
        else if (selector[i2] === "," && nestingLevel === 0) {
          parts2.push(selector.slice(partStartIndex, i2).trim());
          partStartIndex = i2 + 1;
        }
      }
      parts2.push(selector.slice(partStartIndex).trim());
      const pointing = parts2.filter((part) => part.includes(":hover")), resting = parts2.filter((part) => !part.includes(":hover"));
      out += `${head.slice(0, head.length - head.trimStart().length)}${resting.length ? `${resting.join(", ")} {${body}}
` : ""}@media (hover: hover) { ${pointing.join(", ")} {${body}} }`;
    }
    readIndex = closeIndex + 1;
  }
  return out;
}
