  if (document.cookie.indexOf("${DEVICE_KIND_COOKIE}=" + deviceKind) === -1) document.cookie = "${DEVICE_KIND_COOKIE}=" + deviceKind + "; Max-Age=31536000; Path=/; SameSite=Lax" + (location.protocol === "https:" ? "; Secure" : "");
