var BOT_CHECK_SCRIPT = pageScript("bot-check", `(() => {
  const CHECK_ORIGIN = "https://challenges.cloudflare.com";
  const RETRY_COUNT = 3, RETRY_DELAY_MS = 1500, WAIT_TIMEOUT_MS = 20000, INTERACTIVE_WAIT_TIMEOUT_MS = 90000;
  // Cloudflare's script, fetched once, the first time a form needs it, with its connection opened at the same moment
  // for the check's own frame.
  let loading = null;
  const load = () => (loading ||= new Promise((resolve, reject) => {
    if (window.turnstile) return resolve();
    const hint = document.createElement("link");
    hint.rel = "preconnect";
    hint.href = CHECK_ORIGIN;
    document.head.appendChild(hint);
    const script = document.createElement("script");
    script.src = CHECK_ORIGIN + "/turnstile/v0/api.js?render=explicit";
    script.async = true;
    script.onload = () => resolve();
    script.onerror = () => reject();
    document.head.appendChild(script);
  }));
  const sheet = document.getElementById("${BOT_CHECK_SHEET_ID}"), holder = sheet && sheet.querySelector(".bot-check-place");
  document.querySelectorAll("[data-bot-check]").forEach((box, boxIndex) => {
    const ownerKey = String(boxIndex);
    const form = box.closest("form"), field = form.querySelector('input[name="turnstile_token"]');
    // Where Cloudflare's box is drawn: its own place in the sheet, or the form's box on a page without one.
    let place = box;
    if (holder) { place = document.createElement("div"); holder.appendChild(place); }
    const isOurs = () => sheet && sheet.open && sheet.dataset.botCheckOwner === ownerKey;
    // Cloudflare wants its box pressed, and the player has pressed the form's button (never while they're still typing): the sheet opens
    // with this form's box alone in it.
    const askForPress = () => {
      if (!holder || sheet.open) return;
      for (const each of holder.children) each.hidden = each !== place;
      sheet.dataset.botCheckOwner = ownerKey;
      sheet.showModal();
    };
    const errorField = form.querySelector('input[name="turnstile_error_code"]');
    let waiting = null, timer = null, isBroken = false, isStarted = false, isInteractive = false, widgetId = null, retriedCount = 0;
    const settle = () => { clearTimeout(timer); const send = waiting; waiting = null; if (send) send(); };
    const answered = (token) => { field.value = token || ""; if (token && errorField) errorField.value = ""; if (token && isOurs()) sheet.close(); settle(); };
    const giveUp = (code) => { if (errorField && code) errorField.value = String(code).slice(0, 20); isBroken = true; settle(); };
    // Cloudflare's error or timeout: try again a moment later with a fresh widget, a few times, before sending the form without an answer.
    const failed = (code) => {
      field.value = "";
      if (errorField && code) errorField.value = String(code).slice(0, 20);
      if (retriedCount >= RETRY_COUNT || widgetId === null) { giveUp(code); return true; }
      retriedCount += 1;
      setTimeout(() => { try { turnstile.reset(widgetId); } catch { giveUp("reset_failed"); } }, RETRY_DELAY_MS);
      return true;
    };
    const wait = (durationMs) => { clearTimeout(timer); timer = setTimeout(() => giveUp("wait_timeout"), durationMs); };
    const go = () => {
      try {
        widgetId = turnstile.render(place, { sitekey: box.dataset.siteKey, action: box.dataset.botCheck, appearance: "interaction-only", size: (holder ? window.innerWidth < 400 : box.clientWidth < 300) ? "compact" : "normal", retry: "never", "refresh-expired": "auto", callback: answered, "expired-callback": () => (field.value = ""), "error-callback": failed, "timeout-callback": () => failed("interaction_timeout"), "before-interactive-callback": () => { isInteractive = true; if (waiting) { askForPress(); wait(INTERACTIVE_WAIT_TIMEOUT_MS); } } });
      } catch { giveUp("render_failed"); }
    };
    const start = () => { if (isStarted) return; isStarted = true; load().then(go, () => giveUp("script_failed")); };
    for (const type of ["focusin", "pointerdown", "keydown"]) form.addEventListener(type, start, { once: true });
    // Closed without the tick (Close, Esc): a press on the form's button waiting for it goes on, and the page says what to do.
    if (sheet) sheet.addEventListener("close", () => { if (sheet.dataset.botCheckOwner === ownerKey && !field.value && waiting) giveUp("closed_by_player"); });
    form.addEventListener("submit", (event) => {
      start();
      if (field.value || isBroken) return;
      event.preventDefault();
      if (waiting) return;
      const submitter = event.submitter;
      if (isInteractive) askForPress();
      wait(isInteractive ? INTERACTIVE_WAIT_TIMEOUT_MS : WAIT_TIMEOUT_MS);
      waiting = () => form.requestSubmit(submitter);
    });
  });
})();`);

