// apps/site/src/credit-api.ts
async function refundTopUp(env2, ownerId, topUpId, paymentIntentId, amountCents, idempotencyKey) {
  const entryId = newId("credit_entry");
  const nowMs = Date.now();
  const [reserved] = await env2.DB.batch([
    env2.DB.prepare("INSERT INTO credit_entries (id, owner_id, entry_kind, amount_cents, created_at_ms) SELECT ?, ?, 'refund', ?, ? WHERE (SELECT credit_balance_cents FROM owners WHERE id = ?) >= ?").bind(entryId, ownerId, -amountCents, nowMs, ownerId, amountCents),
    env2.DB.prepare("UPDATE owners SET credit_balance_cents = credit_balance_cents - ? WHERE id = ? AND credit_balance_cents >= ?").bind(amountCents, ownerId, amountCents),
    env2.DB.prepare("UPDATE credit_entries SET refunded_cents = refunded_cents + ? WHERE id = ? AND EXISTS (SELECT 1 FROM credit_entries WHERE id = ?)").bind(amountCents, topUpId, entryId)
  ]);
  if (!reserved?.meta.changes) throw new ApiError("top_up_not_refundable", { message: "That top-up's credit was spent a moment ago.", field: "top_up_id", fix: "get_credit shows what each top-up still refunds." });
  try {
    const refund = await refundCharge(env2, paymentIntentId, amountCents, idempotencyKey ?? `refund:${entryId}`);
    await env2.DB.prepare("UPDATE credit_entries SET stripe_object_id = ? WHERE id = ?").bind(refund.id, entryId).run();
    return amountCents;
  } catch (error) {
    await env2.DB.batch([
      env2.DB.prepare("DELETE FROM credit_entries WHERE id = ?").bind(entryId),
      env2.DB.prepare("UPDATE owners SET credit_balance_cents = credit_balance_cents + ? WHERE id = ?").bind(amountCents, ownerId),
      env2.DB.prepare("UPDATE credit_entries SET refunded_cents = refunded_cents - ? WHERE id = ?").bind(amountCents, topUpId)
    ]);
    throw error;
  }
}
async function refundForDeletion(env2, accountId, nowMs = Date.now()) {
  const owner = await env2.DB.prepare("SELECT id FROM owners WHERE account_id = ?").bind(accountId).first();
  if (!owner) return;
  await stopCreditPlanForDeletion(env2, owner.id);
  for (const topUp of await refundableTopUps(env2.DB, owner.id, nowMs)) {
    if (topUp.refundableCents <= 0 || !topUp.stripeObjectId) continue;
    const pendingRefundId = `pending_refund_${topUp.id}`;
    try {
      await refundTopUp(env2, owner.id, topUp.id, topUp.stripeObjectId, topUp.refundableCents, `refund:${pendingRefundId}`);
    } catch (error) {
      console.error("Couldn't refund a deleted account's top-up now; it waits in pending_refunds:", topUp.id, error);
      await env2.DB.prepare("INSERT OR IGNORE INTO pending_refunds (id, stripe_payment_intent_id, amount_cents, created_at_ms) VALUES (?, ?, ?, ?)").bind(pendingRefundId, topUp.stripeObjectId, topUp.refundableCents, nowMs).run();
    }
  }
}
