// apps/site/src/upload.ts
async function deletePrefix(bucket, prefix) {
  let cursor;
  do {
    const list3 = await bucket.list({ prefix: `${prefix}/`, cursor });
    if (list3.objects.length) await bucket.delete(list3.objects.map((object4) => object4.key));
    cursor = list3.truncated ? list3.cursor : void 0;
  } while (cursor);
}

