async function stopCopy(env2, version2, actor) {
  const report = version2.scan_report ? JSON.parse(version2.scan_report) : null;
  if (!report?.matched_game || version2.scan_status === "rejected") return false;
  const rejectedReason = decidedReason("rejected_by_zaisma", "copyright", "A re-upload of another developer's game.");
  await saveScan(env2.DB, version2.id, "rejected", null);
  await env2.DB.prepare("UPDATE versions SET review_reason = ? WHERE id = ?").bind(JSON.stringify(rejectedReason), version2.id).run();
  await noteRulingOnGame(env2, version2.game_id, version2.id);
  await audit(env2.DB, version2.game_id, "rejected", `${version2.id}: a re-upload of another developer's game`, actor, rejectedReason);
  await tellWebhooks(env2, "scan_status_changed", version2.game_id, { versionId: version2.id });
  const original = await gameById(env2.DB, report.matched_game.game_id);
  if (!original || await isBannedOwner(env2, original.owner_id)) return true;
  const copy = await gameById(env2.DB, version2.game_id);
  const uploaderName = await ownerUsername(env2, copy?.owner_id ?? null) ?? "another developer";
  await audit(env2.DB, original.id, "copy-stopped", uploaderName, actor);
  const accountId = original.owner_id ? (await env2.DB.prepare("SELECT account_id FROM owners WHERE id = ?").bind(original.owner_id).first())?.account_id : null;
  const username = await ownerUsername(env2, original.owner_id);
  const email = accountId ? realEmail(await signInEmail(env2, accountId) ?? "") : null;
  if (email && username) await deliverEmail(env2, email, copyStoppedEmail(env2, { username, gameTitle: original.title, uploaderName }));
  return true;
}

