async function alertIfNoticeFixPublished(env2, gameId, versionId2) {
  const game = await gameById(env2.DB, gameId);
  if (!game) return;
  const blocks = readCountryBlocks(game);
  if (blocks.length) {
    const countries = blocks.map((block4) => countryName(block4.country_code)).join(", ");
    await audit(env2.DB, game.id, "notice-fix-published", `${versionId2} is live while the game is blocked in ${countries}`);
    await sendAlert(
      env2,
      `${game.slug}: a fixed version after a country's notice`,
      `${game.title} is blocked in ${countries}:
${blocks.map((block4) => `${block4.country_code}: ${block4.review_reason.message}`).join("\n")}

Its developer published ${versionId2}. Check what the notice names is gone, then lift the block.

Game: ${env2.SITE_ORIGIN}/admin/games/${game.id}`
    );
  }
  if (game.review_status !== "held") return;
  const reason = readReviewReason(game.review_reason);
  if (!reason || !isNoticeReason(reason)) return;
  await audit(env2.DB, game.id, "notice-fix-published", `${versionId2} is live while the game is held on ${reason.code}`);
  await sendAlert(
    env2,
    `${game.slug}: a fixed version after a notice`,
    `${game.title} is held on ${reason.code}: ${reason.message}

Its developer published ${versionId2}. Check what the notice names is gone, then show the game again.

Game: ${env2.SITE_ORIGIN}/admin/games/${game.id}`
  );
}

