var NCMEC_API_URL = "https://report.cybertip.org/ispws";
var NCMEC_LIMITS = {
  /** More accounts than this with a match in one UTC day stop the sending: likelier a broken list than a wave. */
  maximumMatchedAccountCountPerDay: 3,
  /** Tries before a report is failed and Julius files it by hand: about half an hour of the 5-minute job. */
  maximumSendAttemptCount: 6,
  keptDurationDays: 365
};
var DAY_MS11 = 864e5;
var INCIDENT_TYPES = {
  image_match: "Child Pornography (possession, manufacture, and distribution)",
  chat_review: "Online Enticement of Children for Sexual Acts",
  player_report: "Online Enticement of Children for Sexual Acts"
};
var defaultDeps = () => ({ fetch: (input, init) => fetch(input, init) });
var keptBucket = (env2) => env2.REPORTED ? { bucket: env2.REPORTED, prefix: "" } : { bucket: env2.GAMES, prefix: "reported/" };
var keptKeyOf = (env2, reportId, fileIndex) => `${keptBucket(env2).prefix}${reportId}/${fileIndex}`;
var reportById = (env2, id) => env2.DB.prepare("SELECT * FROM ncmec_reports WHERE id = ?").bind(id).first();
var detailsOf = (report) => JSON.parse(report.details_json);
async function accountDetailsOf(env2, accountId) {
  const account = await env2.DB.prepare("SELECT id, username FROM accounts WHERE id = ?").bind(accountId).first();
  if (!account) return null;
  const email = realEmail(await signInEmail(env2, account.id).catch(() => null) ?? "");
  return { account_id: account.id, username: account.username, email };
}
async function keepFile(env2, keptKey, media) {
  const { bucket } = keptBucket(env2);
  let stored = null;
  if (media.gamesKey) {
    const original = await env2.GAMES.get(media.gamesKey);
    if (original) {
      const { readable, writable } = new FixedLengthStream(original.size);
      const [, put] = await Promise.all([original.body.pipeTo(writable), bucket.put(keptKey, readable, { httpMetadata: { contentType: media.contentType } })]);
      stored = put;
    }
  }
  if (!stored && media.bytes) stored = await bucket.put(keptKey, media.bytes, { httpMetadata: { contentType: media.contentType } });
  if (!stored) return null;
  return {
    kept_key: keptKey,
    original_path: media.path,
    content_type: media.contentType,
    size_bytes: stored.size,
    sha256: media.sha256 ?? (media.bytes ? await sha256Hex2(media.bytes) : ""),
    match_message: media.matchMessage,
    is_publicly_available: media.isPubliclyAvailable
  };
}
async function sha256Hex2(bytes) {
  return hexOf(await crypto.subtle.digest("SHA-256", bytes));
}
var hexOf = (buffer) => Array.from(new Uint8Array(buffer), (byte) => byte.toString(16).padStart(2, "0")).join("");
