  game_slugs: nullable2(listOf(SLUG_INPUT, MAXIMUM_WEBHOOK_GAME_COUNT)),
  genres: nullable2(LIST_OF_WORDS),
  glass_tint_color: nullable2(text(40)),
  image: gameData(MAXIMUM_SHADER_BODY_SIZE_BYTES),
  image_id: nullable2(ID_INPUT),
  images: listOf(gameData(PAGE_PREVIEW_LIMITS.maximumBodySizeBytes), PAGE_PREVIEW_LIMITS.maximumImageCount),
  shaders: listOf(gameData(MAXIMUM_SHADER_BODY_SIZE_BYTES), 2),
  images_base64: listOf(text(MAXIMUM_FORUM_POST_BODY_SIZE_BYTES), 100),
  indexeddb_databases: gameData(MAXIMUM_SAVE_BODY_SIZE_BYTES),
  is_answered: yesOrNo,
  inbox_section: nullable2(text(100)),
  is_archived: yesOrNo,
  is_big_update: yesOrNo,
  is_read: yesOrNo,
  reply_text: WALL_TEXT,
  starts_at: TIME_INPUT,
  turned_off_notice_kinds: LIST_OF_WORDS,
  is_kept_out: yesOrNo,
  is_on_game_page: yesOrNo,
  is_public: yesOrNo,
  is_screenshot: yesOrNo,
  is_stripe_tax_used: yesOrNo,
  item_category: WALL_TEXT,
  item_count: COUNT_INPUT,
  item_kind: WALL_TEXT,
  item_name: ID_INPUT,
  keys: anyOf(text(MAXIMUM_SAVE_BODY_SIZE_BYTES), listOf(text(4e3), 1e3)),
  kind: WALL_TEXT,
  known_issue_topic_id: nullable2(ID_INPUT),
  labels: anyOf(text(4e3), listOf(gameData(4096), 100), gameData(4096)),
  links: nullable2(listOf(gameData(8192), 100)),
  link_out_url: nullable2(URL_INPUT),
  local_prices: nullable2(listOf(gameData(1024), 1e3)),
  local_storage_items: gameData(MAXIMUM_SAVE_BODY_SIZE_BYTES),
  match_update_mode: WALL_TEXT,
  maximum_line_count: COUNT_INPUT,
  maximum_topic_count: COUNT_INPUT,
  message: gameData(256 * 1024),
  minimum_level: WALL_TEXT,
  minimum_player_age_years: nullable2(COUNT_INPUT),
