async function deleteGame(env2, deletion) {
  const gameId = deletion.game_id;
  if (deletion.erases_at_ms !== null) await endGameDeletionWait(env2, gameId);
  if (deletion.requested_by_kind !== "zaisma" && await isKeptForChildSafety(env2.DB, gameId)) {
    await cancelGameDeletion(env2.DB, gameId);
    await audit(env2.DB, gameId, "kept-for-review", KEPT_FOR_REVIEW_REASON);
    return;
  }
  const scanning = await env2.DB.prepare("SELECT 1 AS is_scanning FROM versions WHERE game_id = ? AND scan_status = 'scanning' LIMIT 1").bind(gameId).first();
  if (scanning) {
    await postponeGameDeletion(env2.DB, deletion, "A version is still being scanned.");
    return;
  }
  const service = env2.GAME_STORAGE;
  if (!service) {
    await postponeGameDeletion(env2.DB, deletion, "The rooms Worker isn't reachable.");
    return;
  }
  const { failureMessage } = await service.deleteGameStorage(gameId);
  if (failureMessage) {
    await postponeGameDeletion(env2.DB, deletion, failureMessage);
    return;
  }
  let r2CallCount = 0;
  const countR2Call = () => {
    if (++r2CallCount > MAXIMUM_R2_CALL_COUNT) throw new OutOfR2Calls();
  };
  const deleteKeys = async (bucket, keys) => {
    for (let i2 = 0; i2 < keys.length; i2 += R2_DELETE_KEY_COUNT) {
      countR2Call();
      await bucket.delete(keys.slice(i2, i2 + R2_DELETE_KEY_COUNT));
    }
  };
  const deleteUnder = async (bucket, prefix) => {
    for (; ; ) {
      countR2Call();
      const list3 = await bucket.list({ prefix });
      if (list3.objects.length) await deleteKeys(bucket, list3.objects.map((object4) => object4.key));
      if (!list3.truncated) return;
    }
  };
  for (; ; ) {
    const { results: copies } = await env2.DB.prepare("SELECT id, account_id FROM save_history WHERE game_id = ? LIMIT ?").bind(gameId, R2_DELETE_KEY_COUNT).all();
    if (!copies.length) break;
    await deleteKeys(env2.SAVES, copies.map((copy) => saveCopyKey(copy.account_id, gameId, copy.id)));
    await env2.DB.prepare("DELETE FROM save_history WHERE id IN (SELECT value FROM json_each(?))").bind(JSON.stringify(copies.map((copy) => copy.id))).run();
  }
  for (; ; ) {
    const { results: saves } = await env2.DB.prepare("SELECT account_id, version_number, sha256 FROM saves WHERE game_id = ? LIMIT ?").bind(gameId, R2_DELETE_KEY_COUNT / 2).all();
    if (!saves.length) break;
    await deleteKeys(env2.SAVES, saves.flatMap((save) => [saveKey(save.account_id, gameId, save.version_number, save.sha256), unversionedSaveKey(save.account_id, gameId)]));
    await env2.DB.prepare("DELETE FROM saves WHERE game_id = ? AND account_id IN (SELECT value FROM json_each(?))").bind(gameId, JSON.stringify(saves.map((save) => save.account_id))).run();
  }
  const { results: fileVersions } = await env2.DB.prepare("SELECT id FROM versions WHERE game_id = ? AND kind = 'files'").bind(gameId).all();
  await deleteKeys(env2.GAMES, fileVersions.map((version2) => manifestKey(version2.id)));
  await deleteUnder(env2.GAMES, `games/${gameId}/`);
  await deleteUnder(env2.GAMES, `images/${gameId}/`);
  await deleteUnder(env2.GAMES, `shaders/${gameId}/`);
  await deleteUnder(env2.GAMES, heldImageKey(gameId, ""));
  await deleteUnder(env2.GAMES, logPrefix(gameId));
  const { results: reports } = await env2.DB.prepare("SELECT id FROM reports WHERE game_id = ?").bind(gameId).all();
  await deleteKeys(env2.GAMES, reports.map((report) => reportPictureKey(report.id)));
  await env2.DB.batch(gameRowDeletions(env2.DB, gameId));
}

