// apps/site/src/chat-review.ts
var CHAT_REVIEW_DECISIONS = ["false_alarm", "remove_chat", "report_to_ncmec"];
async function decideChatReview(env2, review, decision, actor) {
  const nowMs = Date.now();
  if (decision === "false_alarm") {
    await env2.DB.batch([
      env2.DB.prepare("DELETE FROM chat_reviews WHERE id = ?").bind(review.id),
      env2.DB.prepare("UPDATE accounts SET chat_stopped_reason = NULL, chat_stopped_until_ms = NULL WHERE id = ? AND chat_stopped_reason IN ('in_review', 'removed') AND social_stopped_at_ms IS NULL AND NOT EXISTS (SELECT 1 FROM chat_reviews WHERE sender_account_id = ?)").bind(review.sender_account_id, review.sender_account_id)
    ]);
  } else {
    await env2.DB.batch([
      env2.DB.prepare("UPDATE chat_reviews SET chat_review_status = 'confirmed', decided_at_ms = COALESCE(decided_at_ms, ?), kept_until_ms = ? WHERE id = ?").bind(nowMs, nowMs + CHAT_FILTER_LIMITS.reviewKeptMs, review.id),
      env2.DB.prepare("UPDATE accounts SET chat_stopped_reason = 'removed', chat_stopped_until_ms = NULL WHERE id = ?").bind(review.sender_account_id)
    ]);
  }
  await audit(env2.DB, review.game_id, `chat-review-${decision.replace(/_/g, "-")}`, review.id, actor);
  if (decision === "false_alarm") {
    await env2.DB.prepare("DELETE FROM ncmec_reports WHERE chat_review_id = ? AND ncmec_report_status = 'ready'").bind(review.id).run();
    return;
  }
  const ready = await readyChatReviewReport(env2, review.id, nowMs);
  if (decision === "report_to_ncmec" && ready) await sendByPerson(env2, ready.id, actor);
}

