    outputSchema: object({ webhook: WEBHOOK, signing_secret: nullable(text2("The new signing secret when replace_signing_secret was true, shown only this once; null otherwise.")), next_steps: NEXT }),
    annotations: { readOnlyHint: false, destructiveHint: false, openWorldHint: false },
