    inputSchema: { ...object2({ slug, room_code: ROOM_CODE_INPUT, message: ROOM_MESSAGE_INPUT }, ["slug", "room_code", "message"]), examples: [{ slug: "frostbound", room_code: "K7Q2MX", message: { kind: "freeze", player_id: "player_3k9x2m7q1z8b4n5w6r0t" } }] },
