var knownImages = (version2) => version2.scan_report ? JSON.parse(version2.scan_report).findings.some((finding) => finding.code === KNOWN_IMAGE_CODE) : false;
var pickedRule = (form) => {
  const picked = form.get("content_rule");
  return isContentRule(picked) ? picked : null;
};
function noticeItems(gameId, reviewStatus, reason) {
  if (reviewStatus === "removed") return [words3("Taken down, so a notice can't hold it.")];
  if (reviewStatus === "held" && isNoticeReason(reason)) {
    return [words3("Held on a notice. Show it again (under Takedown) once the live version no longer has what the notice names, or 10 working days after you passed a counter-notice on, unless the sender says they've gone to court.")];
  }
  return [
    formBlock(`/admin/games/${gameId}/notice`, [
      control2(selectField({ name: "notice_kind", id: "notice-kind", label: "The kind of notice", placeholder: "Pick the kind", choices: NOTICE_KINDS.map((kind) => ({ label: kind === "copyright" ? "Copyright (DMCA)" : `${kind[0].toUpperCase()}${kind.slice(1)}`, choiceValue: kind })) })),
      control2(reasonField({ idPrefix: "notice", isRequired: true, label: "What it names, which the developer reads" })),
      buttons([secondaryButton("Hold on this notice", { type: "submit" })])
    ])
  ];
}
function countryBlockItems(game) {
  const blocks = readCountryBlocks(game);
  return [
    adminTable("Country blocks", [{ label: "Country" }, { label: "What it names", isLongText: true }, { label: "Since" }, { label: "Lift", isActions: true }], blocks.map((countryBlock) => [
      `${countryName(countryBlock.country_code)} (${countryBlock.country_code})`,
      countryBlock.review_reason.message,
      new Date(countryBlock.blocked_at_ms).toISOString().slice(0, 10),
      html`<form method="post" action="/admin/games/${game.id}/country-block-lift"><input type="hidden" name="country_code" value="${countryBlock.country_code}">${secondaryButton("Lift", { isSmall: true, type: "submit" })}</form>`
    ]), "Not blocked in any country."),
    formBlock(`/admin/games/${game.id}/country-block`, [
      control2(cutField({ name: "country_code", id: "country-block-code", label: "The country, as its two-letter code", type: "text", placeholder: "GB", maximumCharacterCount: 2, isUppercase: true, characterPattern: "[A-Za-z]", isShort: true, isRequired: true })),
      control2(reasonField({ idPrefix: "country-block", isRequired: true, label: "Which law and what it names, which the developer reads" })),
      buttons([secondaryButton("Block in that country", { type: "submit" })])
    ])
  ];
}
