  await noteRulingOnGame(env2, gameId);
  await recordRestoreEvent(env2, { event_kind: "game_removed", at_ms: Date.now(), game_id: gameId, review_reason: removedReason });
  await closeReports(env2.DB, gameId, "actioned");
