function devSheetBody(name, view) {
  if (name === "phone") {
    if (!view.networkUrl) return String(html`<p class="bm-note">${icon("phone")} On a phone: start the bench again with --on-network, and the QR code for a phone on the same Wi-Fi shows here.</p>`);
    const target = view.roomCode ? `${view.networkUrl}/?room=${view.roomCode}` : `${view.networkUrl}/`;
    return String(html`<p class="bm-label">${icon("phone")} On a phone, on the same Wi-Fi</p>
<img class="bm-qr" src="/bench/qr.svg?text=${encodeURIComponent(target)}" alt="A QR code for ${target}" width="150" height="150">
<p class="bm-url">${target}</p>
<p class="bm-warn">${icon("warning")} Your phone will say the connection isn't private, because the bench signs its own certificate. Continue to the site.</p>`);
  }
  if (!view.logLines.length) return String(html`<p class="bm-note">Nothing yet.</p>`);
  return String(html`<ol class="bm-log">${view.logLines.map((line) => html`<li>${line}</li>`)}</ol>`);
}
var AGE_BAND_WORDS = { "13-15": "13\u201315", "16-17": "16\u201317", "18+": "18+" };
var isSocialModeAllowed = (ageBand2, socialMode) => socialModesFor(ageBand2).includes(socialMode);
var startingSocialMode = (ageBand2) => defaultSocialMode(ageBand2);
var takesFriendRequests = (ageBand2, socialMode) => socialModeSettings(socialMode, ageBand2).who_can_send_friend_requests !== "nobody";
function chatOf(ageBand2) {
  return { whoReadsMyChat: defaultWhoReadsMyChat(ageBand2), bandGroup: chatBandGroup({ age_band: ageBand2 }) };
}
var face = (name) => html`<span class="bp-face" aria-hidden="true">${name.slice(0, 1).toUpperCase()}</span>`;
var describe2 = (player) => `${AGE_BAND_WORDS[player.ageBand]} \xB7 ${SOCIAL_MODE_LABELS[player.socialMode]}`;
var call2 = (method, path, body = {}) => html` data-bench-call="${method} ${path}" data-bench-body="${JSON.stringify(body)}"`;
var playerPath = (playerId2) => `/bench/api/players/${encodeURIComponent(playerId2)}`;
var ageSelect = (ageBand2, attributes = "") => html`<select class="bp-select" name="age_band" aria-label="Age"${attributes}>${AGE_BANDS.map((each) => html`<option value="${each}"${each === ageBand2 ? raw(" selected") : ""}>${AGE_BAND_WORDS[each]}</option>`)}</select>`;
var socialSelect = (socialMode, attributes = "") => html`<select class="bp-select" name="social_mode" aria-label="How they play"${attributes}>${SOCIAL_MODES.map((each) => html`<option value="${each}"${each === socialMode ? raw(" selected") : ""}>${SOCIAL_MODE_LABELS[each]}</option>`)}</select>`;
function playersPanelHtml(place, input) {
  const rows = input.players.map((player) => {
    const isCurrent = player.playerId === input.currentPlayerId;
    const elsewhere = player.openPlayerNumbers.filter((openNumber) => openNumber !== place.playerNumber);
    return html`<div class="bp-row${isCurrent ? " is-current" : ""}"><button class="bp-open" type="button" data-bench-view="player" data-player-id="${player.playerId}">${face(player.name)}<span class="bp-who"><b>${player.name}</b><span class="bp-meta">${describe2(player)}</span></span></button>${isCurrent ? html`<span class="bp-tag">this tab</span>` : html`${elsewhere.length ? html`<span class="bp-tag">in another tab</span>` : ""}<button class="bp-ghost" type="button" data-bench-play-as="${player.playerId}">Play as</button>`}</div>`;
  });
  return String(html`<div class="bp-head"><b>Players</b><button class="bp-btn" type="button"${call2("POST", "/bench/api/players")}>+ Quick</button><button class="bp-ghost" type="button" data-bench-view="new">New</button>${place.isPage ? "" : html`<button class="bp-link" type="button" data-bench-panel="close" aria-label="Close the panel">✕</button>`}</div>
<input class="bp-search" type="search" placeholder="Find a player" aria-label="Find a player" value="${input.searchText}" data-bench-search>
${rows.length ? rows : html`<p class="bp-empty">${input.searchText ? "No one by that name." : "No players yet. + Quick makes one with the next name and the defaults."}</p>`}
<div class="bp-foot"><span>${input.totalCount === 1 ? "1 player" : `${input.totalCount} players`} on this computer</span><button class="bp-ghost" type="button" data-bench-play-as="guest">Play as a guest</button></div>`);
}
function newPlayerPanelHtml(input) {
  return String(html`<div class="bp-head"><button class="bp-link" type="button" data-bench-view="list" aria-label="Back to players">‹</button><b>New player</b></div>
<div class="bp-section" data-bench-form><input class="bp-input" name="name" value="${input.suggestedName}" maxlength="20" aria-label="Name">
<div class="bp-pair">${ageSelect("18+")}${socialSelect(startingSocialMode("18+"))}</div>
<p class="bp-note">Zaisma's own age and social rules: 13–15 is never open and social.</p>
<p class="bp-error" data-bench-error hidden></p>
<button class="bp-btn" type="button" data-bench-make>Make player</button></div>`);
}
function playerPanelHtml(place, input) {
  const { player } = input;
  const here = playerPath(player.playerId);
  const tabButton = (tab2, label) => html`<button type="button" data-bench-tab="${tab2}"${tab2 === input.tab ? raw(' aria-current="page"') : ""}>${label}</button>`;
  const pick2 = (list3, label, kind) => {
    const choices2 = input.others.filter((other) => !list3.some((each) => each.playerId === other.playerId));
    return choices2.length ? html`<select class="bp-select" aria-label="${label}" data-bench-add="${here}/${kind}/"><option value="">${label}</option>${choices2.map((other) => html`<option value="${other.playerId}">${other.name}</option>`)}</select>` : "";
  };
  let section;
  if (input.tab === "profile") {
    section = html`<div class="bp-section"><input class="bp-input" name="name" value="${player.name}" maxlength="20" aria-label="Name" data-bench-field="${here}">
<div class="bp-pair">${ageSelect(player.ageBand, html` data-bench-field="${here}"`)}${socialSelect(player.socialMode, html` data-bench-field="${here}"`)}</div>
<p class="bp-error" data-bench-error hidden></p>
<h3>Friends</h3>
${input.friends.length ? input.friends.map((friend) => html`<div class="bp-line"><span>${friend.name}</span><button class="bp-link" type="button"${call2("DELETE", `${here}/friends/${friend.playerId}`)}>Remove</button></div>`) : html`<p class="bp-note">No friends yet.</p>`}
${pick2(input.friends, "+ Add a friend", "friends")}
<h3>Blocks</h3>
${input.blocked.length ? input.blocked.map((other) => html`<div class="bp-line"><span>${other.name}</span><button class="bp-link" type="button"${call2("DELETE", `${here}/blocks/${other.playerId}`)}>Unblock</button></div>`) : html`<p class="bp-note">${player.name} hasn't blocked anyone.</p>`}
${input.blockedBy.length ? html`<p class="bp-note">Blocked by ${input.blockedBy.join(", ")}. A block holds both ways in the game's passes.</p>` : ""}
${pick2(input.blocked, "+ Block a player", "blocks")}
<p class="bp-note">A change reaches the game with ${player.name}'s next pass: the next time they join a room.</p>
<div class="bp-line"><span></span><button class="bp-link" type="button" data-bench-delete="${here}" data-player-name="${player.name}">Delete ${player.name}</button></div></div>`;
  } else {
    const purchaseLine = (purchase) => html`<div class="bp-line bp-purchase"><span class="bp-meta">${purchase.detail}</span>${purchase.isRefunded ? "" : html`<button class="bp-link" type="button"${call2("POST", `${here}/purchases/${purchase.purchaseId}/refund`)}>Refund</button>`}</div>`;
    section = html`<input class="bp-search" type="search" placeholder="Find an item" aria-label="Find an item" value="${input.searchText}" data-bench-search>
${input.items.length ? input.items.map((gameItem) => html`<div class="bp-item"><div class="bp-line"><span class="bp-who"><b>${gameItem.title}</b><span class="bp-meta">${[gameItem.itemKind, gameItem.priceText, ...gameItem.isOwned ? ["owned"] : []].join(" \xB7 ")}</span></span>${gameItem.isOwned && gameItem.itemKind === "permanent" ? html`<button class="bp-ghost" type="button"${call2("DELETE", `${here}/items/${gameItem.itemName}`)}>Take away</button>` : html`<button class="bp-ghost" type="button"${call2("POST", `${here}/items`, { item_name: gameItem.itemName })}>${gameItem.itemKind === "consumable" ? "Grant 1" : "Grant"}</button>`}</div>${gameItem.purchases.map(purchaseLine)}</div>`) : html`<p class="bp-empty">${input.searchText ? "No item by that name." : "No items: they're set on Zaisma, and the bench brings them in with --game and ZAISMA_KEY."}</p>`}
<p class="bp-note" style="padding:8px 10px">A grant is a purchase the game gets as Zaisma would send it, and a refund reaches it as Zaisma's would. "Waiting for the game" is one it hasn't handled yet.</p>`;
  }
  return String(html`<div class="bp-head"><button class="bp-link" type="button" data-bench-view="list" aria-label="Back to players">‹</button>${face(player.name)}<b>${player.name}</b>${input.isCurrent ? html`<span class="bp-tag">this tab</span>` : html`<button class="bp-btn" type="button" data-bench-play-as="${player.playerId}">Play as ${player.name}</button>`}</div>
<p class="bp-note" style="padding:6px 10px 0">${describe2(player)}${player.openPlayerNumbers.length ? ` \xB7 open in ${player.openPlayerNumbers.length === 1 ? "a tab" : `${player.openPlayerNumbers.length} tabs`}` : ""}</p>
<div class="bp-tabs" role="tablist">${tabButton("profile", "Profile")}${tabButton("items", "Items")}</div>
${section}`);
}
